"use client";

import { Calendar as AriaCalendar, RangeCalendar as AriaRangeCalendar } from "react-aria-components";
import type {
  CalendarProps as AriaCalendarProps,
  DateValue,
  RangeCalendarProps as AriaRangeCalendarProps,
} from "react-aria-components";
import { MonthPanel } from "@/components/base/date-picker/shared";
import { cx } from "@/lib/cx";

/**
 * Date calendar — a month on the page rather than in a popover: pick a day
 * for a booking, a deadline, a range of nights.
 *
 *   <DateCalendar aria-label="Delivery date" value={date} onChange={setDate} />
 *   <DateRangeCalendar aria-label="Stay" value={range} onChange={setRange} />
 *
 * Date Picker's month panel, as is: the card, the 16px month chevrons, the
 * 32px day cells 12px apart with the selected day's accent pill and the
 * range band that bridges the gaps. Today carries a small accent dot, and
 * days ruled out by `isDateUnavailable` are struck through.
 *
 * Built on React Aria's Calendar and RangeCalendar: arrows move by day,
 * Page Up and Page Down by month (with Shift, by year), Home and End to the
 * month's first and last day, and Enter picks. `minValue` and `maxValue`
 * fade the days outside them. Values are dates from @internationalized/date.
 */

export interface DateCalendarProps<T extends DateValue> extends Omit<AriaCalendarProps<T>, "className" | "children" | "visibleDuration"> {
  /** Mark today with a dot. Default true. */
  showToday?: boolean;
  className?: string;
}

export function DateCalendar<T extends DateValue>({ showToday = true, className, ...props }: DateCalendarProps<T>) {
  return (
    <AriaCalendar {...props} className={cx("inline-flex outline-none", className)}>
      <MonthPanel offset={0} showPrev showNext showToday={showToday} />
    </AriaCalendar>
  );
}

export interface DateRangeCalendarProps<T extends DateValue>
  extends Omit<AriaRangeCalendarProps<T>, "className" | "children" | "visibleDuration"> {
  /** One month, or two side by side (default). They stack when the space is narrow. */
  visibleMonths?: 1 | 2;
  /** Mark today with a dot. Default true. */
  showToday?: boolean;
  className?: string;
}

export function DateRangeCalendar<T extends DateValue>({
  visibleMonths = 2,
  showToday = true,
  className,
  ...props
}: DateRangeCalendarProps<T>) {
  return (
    <AriaRangeCalendar
      {...props}
      visibleDuration={{ months: visibleMonths }}
      className={cx("inline-flex outline-none", className)}
    >
      <div className="flex flex-wrap justify-center gap-2">
        {visibleMonths === 2 ? (
          <>
            <MonthPanel offset={0} showPrev showToday={showToday} />
            <MonthPanel offset={1} showNext showToday={showToday} />
          </>
        ) : (
          <MonthPanel offset={0} showPrev showNext showToday={showToday} />
        )}
      </div>
    </AriaRangeCalendar>
  );
}

"use client";

import { useId, useRef, useState } from "react";
import type { ReactNode, RefObject } from "react";
import { Calendar, Dialog, Popover } from "react-aria-components";
import type { CalendarDate } from "@internationalized/date";
import { QiCalendar } from "@/components/qiguan/icons";
import { AnimatePresence, motion } from "motion/react";
import { Button } from "@/components/base/buttons/button";
import {
  DateChipInput,
  MonthPanel,
  formatTriggerDate,
  popoverClassName,
  triggerButtonClassName,
} from "@/components/base/date-picker/shared";
import { cx } from "@/lib/cx";
import { useDismissOnOutsidePress } from "@/lib/use-dismiss-on-outside-press";

/**
 * Figma source: Qiguan UI → "Calendar_single" (node 3879:6708).
 *
 * A single-date picker: trigger button opens a popover with one month
 * (react-aria's plain `Calendar`, so both nav chevrons are fully functional —
 * unlike `DateRangePicker`'s dual view, there's only one month to navigate)
 * and a footer with an editable "DD/MM/YYYY" chip plus Cancel/Apply. No
 * quick-select sidebar in this Figma frame.
 *
 * Reuses the exact chevrons, day-cell rendering, month-panel chrome, editable
 * date chip, and trigger/popover surfaces built for `DateRangePicker` — see
 * `./shared`. A plain `Calendar`'s `CalendarCellRenderProps` always reports
 * `isSelectionStart === isSelectionEnd === isSelected` for the one chosen
 * day, so the shared `DayCell` renders it as a single fully-rounded pill
 * with no connecting range background, matching Figma without any
 * single-vs-range branching in the cell itself.
 *
 * Standalone `Popover` + `triggerRef` (like `MeetingScheduler`), not
 * `DialogTrigger`, so an external trigger can be swapped in: pass
 * `triggerRef`/`isOpen`/`onOpenChange` to anchor the popover to your own
 * element (e.g. the calendar template's month-switcher label) instead of
 * DatePicker's own button, which is hidden in that case.
 */

export interface DatePickerProps {
  value?: CalendarDate | null;
  defaultValue?: CalendarDate | null;
  onChange?: (value: CalendarDate | null) => void;
  isDisabled?: boolean;
  className?: string;
  "aria-label"?: string;
  /** 字段标签。传了之后在触发器上方渲染标签，并把它作为弹层的无障碍名。
   *  与 `Input` / `Select` 的 `label` 同义；为字符串时优先于 `aria-label`。 */
  label?: ReactNode;
  /** 字段说明，渲染在触发器下方。与 `Input` / `Select` 的 `hint` 同义。 */
  hint?: ReactNode;
  /** 标签后的必填星号。 */
  isRequired?: boolean;
  /** Anchor the popover to an external element instead of DatePicker's own
   *  trigger button (which is hidden when this is provided). Pair with
   *  `isOpen`/`onOpenChange` for full external control. */
  triggerRef?: RefObject<HTMLElement | null>;
  isOpen?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
}

export function DatePicker({
  value,
  defaultValue = null,
  onChange,
  isDisabled,
  className,
  "aria-label": ariaLabel = "日期",
  label,
  hint,
  isRequired = false,
  triggerRef: externalTriggerRef,
  isOpen: controlledIsOpen,
  onOpenChange: controlledOnOpenChange,
}: DatePickerProps) {
  const ownTriggerRef = useRef<HTMLButtonElement>(null);
  const triggerRef = externalTriggerRef ?? ownTriggerRef;
  const isExternal = externalTriggerRef !== undefined;
  const popoverRef = useRef<HTMLElement>(null);

  const [internalOpen, setInternalOpen] = useState(false);
  const isOpen = isExternal ? (controlledIsOpen ?? false) : internalOpen;
  const setIsOpen = isExternal ? (controlledOnOpenChange ?? (() => {})) : setInternalOpen;

  const isControlled = value !== undefined;
  const [internalValue, setInternalValue] = useState<CalendarDate | null>(defaultValue);
  const committedValue = isControlled ? (value ?? null) : internalValue;

  const [pendingValue, setPendingValue] = useState<CalendarDate | null>(committedValue);
  // React Aria's `Calendar` keeps its own internal `visibleRange` state for
  // as long as it stays mounted (Popover keeps its content mounted between
  // opens for the exit animation), so it never re-derives the visible month
  // from a later `value` change on its own. Bumping this on every open and
  // keying `Calendar` on it forces a fresh mount showing the right month —
  // needed for the external-trigger case, where `value` can jump (e.g. the
  // calendar template's month switcher) between one open and the next.
  const [openKey, setOpenKey] = useState(0);

  // Re-sync the calendar's displayed month/selection to the current
  // committed value every time the popover opens — not just when DatePicker's
  // own trigger toggles it, but also when `isOpen` is flipped true by an
  // external trigger (`triggerRef`), which never runs `openChange` below.
  //
  // 原来是 `useEffect(..., [isOpen])`，触发 react-hooks/set-state-in-effect。
  // 改成渲染期调整（React 官方「prop 变化时调整 state」模式）：effect 在提交
  // **之后**才跑，意味着弹层开的那一帧先挂载了旧月份的 `Calendar`、再被 bump
  // 的 key 重挂载一次；渲染期调整把这件事提前到提交**之前**，第一帧就是正确的
  // 月份，且少一次提交。`lastOpen` 是收敛哨兵，只在开合翻转时调整一次。
  const [lastOpen, setLastOpen] = useState(isOpen);
  if (isOpen !== lastOpen) {
    setLastOpen(isOpen);
    // 只在「打开」这一侧重置；关闭时保留上次的 pendingValue，让退场动画
    // 仍然显示用户刚看的那一屏，而不是闪回 committedValue。
    if (isOpen) {
      setPendingValue(committedValue);
      setOpenKey((k) => k + 1);
    }
  }

  const commit = (next: CalendarDate | null) => {
    if (!isControlled) setInternalValue(next);
    onChange?.(next);
    setIsOpen(false);
  };

  const openChange = (open: boolean) => {
    setIsOpen(open);
  };

  useDismissOnOutsidePress(isOpen, () => setIsOpen(false), [triggerRef, popoverRef]);

  const triggerId = useId();
  const hintId = useId();
  // 有 `label` 时用它做弹层的无障碍名，否则退回 `aria-label`
  const resolvedAriaLabel = typeof label === "string" ? label : ariaLabel;

  // 触发器单独抽成变量：有 `label` 时要把它包进「标签 + 控件 + 说明」的结构，
  // 没有时必须原样返回，不能多包一层 div —— 否则所有既有调用点的布局都会变。
  const triggerButton = (
    <button
      id={label ? triggerId : undefined}
      ref={ownTriggerRef}
      type="button"
      disabled={isDisabled}
      aria-describedby={hint ? hintId : undefined}
      onClick={() => openChange(!isOpen)}
      className={cx(triggerButtonClassName, className)}
    >
      {/* 图标是「此控件可点开」的标记，不是内容 —— 与 `Select` 的箭头取同一档
          （`text-text-secondary`）。原先用 `foreground-icon-primary`（近黑），
          比它自己的空态文字还重，会是「图标最黑、文字最浅」的反向层级。 */}
      <QiCalendar className="size-5 shrink-0 text-text-secondary" aria-hidden />
      {/* 空态「选择日期」是 placeholder，必须与 `Input` 的
          `placeholder:text-text-tertiary` 同色。这里原先不分有值/无值一律
          `text-text-primary`，结果「还没选」的日期框看起来像「已经选了」——
          与同一行里浅灰的 Input placeholder 并排，就是两种深浅的三档混乱。 */}
      <span
        className={cx(
          "flex items-center justify-center whitespace-nowrap px-1 text-body-medium",
          committedValue ? "text-text-primary" : "text-text-tertiary",
        )}
      >
        {committedValue ? formatTriggerDate(committedValue) : "选择日期"}
      </span>
    </button>
  );

  return (
    <>
      {!isExternal &&
        (label ? (
          <div className={cx("flex w-full flex-col gap-1")}>
            <label
              htmlFor={triggerId}
              className={cx("flex cursor-default items-center gap-0.5 text-body-medium text-text-primary")}
            >
              {label}
              {isRequired && (
                <span aria-hidden="true" className={cx("text-body-medium text-text-error-primary")}>
                  *
                </span>
              )}
            </label>
            {triggerButton}
            {hint && (
              <span id={hintId} className={cx("pt-px text-caption-1-medium text-text-secondary")}>
                {hint}
              </span>
            )}
          </div>
        ) : (
          triggerButton
        ))}
      <Popover
        ref={popoverRef}
        triggerRef={triggerRef}
        isOpen={isOpen}
        onOpenChange={openChange}
        offset={4}
        placement="bottom end"
        isNonModal
        className={popoverClassName}
      >
        <Dialog aria-label={resolvedAriaLabel} className="outline-none">
          <Calendar key={openKey} aria-label={resolvedAriaLabel} value={pendingValue} onChange={setPendingValue}>
            <div className="flex flex-col pt-2 pr-2 pb-3 pl-2">
              <MonthPanel offset={0} showPrev showNext />
              <div className="flex items-center justify-between pt-3 pr-4 pl-4">
                <div>
                  <AnimatePresence>
                    {pendingValue && (
                      <motion.div
                        key="date-summary"
                        initial={{ opacity: 0, y: -12 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -12 }}
                        transition={{ duration: 0.25, ease: [0.34, 1.2, 0.64, 1] }}
                      >
                        <DateChipInput date={pendingValue} label="日期" onCommit={setPendingValue} />
                      </motion.div>
                    )}
                  </AnimatePresence>
                </div>
                <div className="flex items-center gap-2.5">
                  <Button
                    variant="secondary"
                    onClick={() => {
                      setPendingValue(committedValue);
                      setIsOpen(false);
                    }}
                  >
                    取消
                  </Button>
                  <Button onClick={() => commit(pendingValue)} disabled={!pendingValue}>
                    应用
                  </Button>
                </div>
              </div>
            </div>
          </Calendar>
        </Dialog>
      </Popover>
    </>
  );
}

"use client";

import { useState, useContext } from "react";
import {
  Button as RACButton,
  CalendarCell,
  CalendarGrid,
  CalendarGridBody,
  CalendarGridHeader,
  CalendarHeaderCell,
  CalendarStateContext,
  RangeCalendarStateContext,
} from "react-aria-components";
import type { CalendarCellRenderProps } from "react-aria-components";
import { CalendarDate, getLocalTimeZone } from "@internationalized/date";
import { cx } from "@/lib/cx";

/**
 * Shared building blocks for the base/date-picker family — `DateRangePicker`
 * (dual-month, node 3871:5738) and `DatePicker` (single-month, node
 * 3879:6708) are the same visual system (month panel, day cell, editable
 * date chip) around two different react-aria-components roots
 * (`RangeCalendar` vs `Calendar`). Keeping the pieces here means a Figma
 * fidelity fix only has to happen once.
 */

/** Exact paths from Figma's month-nav chevrons (node 3869:5461 / 3869:5528) — a
 *  16×16 glyph, 2px round-capped stroke, mirrored around x=8. */
export function ChevronLeft16({ className }: { className?: string }) {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" className={className} aria-hidden>
      <path
        d="M9 4L5.70711 7.29289C5.31658 7.68342 5.31658 8.31658 5.70711 8.70711L9 12"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
      />
    </svg>
  );
}

export function ChevronRight16({ className }: { className?: string }) {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" className={className} aria-hidden>
      <path
        d="M7 4L10.2929 7.29289C10.6834 7.68342 10.6834 8.31658 10.2929 8.70711L7 12"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
      />
    </svg>
  );
}

/**
 * 日期格式化必须用的 locale —— **不能传 `undefined` 交给运行时决定**。
 *
 * `new Intl.DateTimeFormat(undefined, …)` 用的是「运行环境的默认语言」：
 * 服务端 Node 是 `en-US`，浏览器跟随用户语言（中文环境是 `zh-CN`）。
 * 于是同一份标记在两端渲染成两个字符串 —— 服务端 `Sep 18, 2026`、
 * 客户端 `2026年9月18日` —— 直接命中 React 的 hydration mismatch，
 * 整棵子树在客户端被重新生成（页面闪一下、控制台报错）。
 *
 * 全站 locale 由 `AppI18nProvider` 钉在 `zh-CN`（见
 * components/application/providers/app-i18n-provider.tsx），
 * 这里的裸 `Intl` 调用拿不到那个 context，所以显式写上同一个值，
 * 两处保持一致。改 locale 时这两个地方要一起改。
 */
const DATE_LOCALE = "zh-CN";

export function formatTriggerDate(date: CalendarDate) {
  return new Intl.DateTimeFormat(DATE_LOCALE, {
    month: "short",
    day: "numeric",
    year: "numeric",
  }).format(date.toDate(getLocalTimeZone()));
}

export function formatChipDate(date: CalendarDate) {
  return `${String(date.day).padStart(2, "0")}/${String(date.month).padStart(2, "0")}/${date.year}`;
}

/** Parses the chip's own "DD/MM/YYYY" format back into a CalendarDate, or
 *  null if the text isn't a valid date (out-of-range day/month is rejected
 *  up front; CalendarDate itself constrains impossible day-in-month combos
 *  like Feb 30). */
export function parseChipDate(text: string): CalendarDate | null {
  const match = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(text.trim());
  if (!match) return null;
  const day = Number(match[1]);
  const month = Number(match[2]);
  const year = Number(match[3]);
  if (month < 1 || month > 12 || day < 1 || day > 31) return null;
  return new CalendarDate(year, month, day);
}

export function DayCell(props: CalendarCellRenderProps & { isRange: boolean; showToday?: boolean }) {
  const { date, formattedDate, isSelected, isSelectionStart, isSelectionEnd, isHovered, isFocusVisible, isDisabled, isUnavailable, isToday, isOutsideMonth, isRange, showToday = false } = props;

  if (isOutsideMonth) {
    return <div className="size-8" />;
  }

  const dayOfWeek = date.toDate(getLocalTimeZone()).getDay(); // 0 = Sun ... 6 = Sat

  // A plain (non-range) Calendar never sets isSelectionStart/isSelectionEnd —
  // those are range-only concepts, so they stay false even for the one
  // selected day. Without isRange, that day would fall through to the
  // "middle of a range" backdrop path instead of rendering as its own pill.
  const isSingleDay = isRange ? isSelectionStart && isSelectionEnd : isSelected;
  const isEdge = isRange ? isSelectionStart || isSelectionEnd : isSelected;

  // Cells sit 12px apart (Figma's row/column gap). A selected range should
  // still read as one continuous band, so the background bridges that gap by
  // extending half of it (6px) toward each selected neighbor — never past
  // the first/last column of a row, where there's no neighbor to bridge to.
  // Only meaningful for a RangeCalendar; a plain Calendar never bridges.
  const extendLeft = isRange && isSelected && !isSelectionStart && dayOfWeek !== 0;
  const extendRight = isRange && isSelected && !isSelectionEnd && dayOfWeek !== 6;

  // The blue backgrounds fade in/out on opacity instead of popping instantly.
  // Both layers always render (geometry computed regardless of selection) so
  // toggling opacity is a plain CSS transition, not a mount/unmount — that
  // keeps ~70 cells worth of range changes cheap and reliably animated.
  // border-radius rides the same transition as opacity: the rounding classes
  // still flip instantly on deselect (the shape a cell "should" have has no
  // in-between state), but transitioning the property means it eases toward
  // square in sync with the fade instead of snapping to square immediately
  // while the color is still visible.
  return (
    <div className="relative size-8">
      <span
        aria-hidden
        className={cx(
          "absolute inset-y-0 bg-date-range-background transition-[opacity,border-radius] duration-100 ease-out",
          isSelectionStart ? "left-1/2" : extendLeft ? "-left-1.5" : "left-0",
          isSelectionEnd ? "right-1/2" : extendRight ? "-right-1.5" : "right-0",
          !isSelectionStart && dayOfWeek === 0 && "rounded-l-lg",
          !isSelectionEnd && dayOfWeek === 6 && "rounded-r-lg",
          isSelected && !isSingleDay ? "opacity-100" : "opacity-0",
        )}
      />
      <div
        className={cx(
          "relative flex size-8 items-center justify-center rounded-lg outline-none",
          !isSelected && isHovered && "bg-background-secondary-hover",
          "transition-colors duration-100 ease-out",
          isFocusVisible && "ring-2 ring-inset ring-border-focus-ring",
        )}
      >
        <span
          aria-hidden
          className={cx(
            "absolute inset-0 bg-date-range-edge-background transition-[opacity,border-radius] duration-100 ease-out",
            isSingleDay && "rounded-lg",
            isSelectionStart && !isSingleDay && "rounded-l-lg",
            isSelectionEnd && !isSingleDay && "rounded-r-lg",
            isEdge ? "opacity-100" : "opacity-0",
          )}
        />
        <span
          className={cx(
            "relative text-body-medium text-text-primary",
            (isDisabled || isUnavailable) && "text-text-tertiary",
            // 不可选的日子可以聚焦但不能选，所以只淡下去容易被当成「选不了但看得见」，
            // 加一道删除线才说得清。
            isUnavailable && "line-through",
          )}
        >
          {formattedDate}
        </span>
        {/* 今天：默认不画（选择器里当前日期是被选中的那一天，再点一个点反而乱），
            由内嵌日历（Date Calendar）显式打开。 */}
        {showToday && isToday ? (
          <span
            aria-hidden
            className={cx(
              "absolute bottom-1 left-1/2 size-1 -translate-x-1/2 rounded-full",
              isEdge ? "bg-text-primary" : "bg-accent-500",
            )}
          />
        ) : null}
      </div>
    </div>
  );
}

export function MonthPanel({
  offset,
  showPrev,
  showNext,
  showToday = false,
  bare = false,
  hideHeader = false,
}: {
  offset: number;
  showPrev?: boolean;
  showNext?: boolean;
  /** 在今天下面点一个小圆点 —— 内嵌日历用，选择器不用（见 DayCell 注释）。 */
  showToday?: boolean;
  /** Skip the panel's own card chrome (width, bg, padding, shadow) so it can
   *  be embedded directly inside a caller-styled container instead — used by
   *  the calendar template's inline month switcher, which supplies its own
   *  card (matching a different surface's border/shadow). */
  bare?: boolean;
  /** Skip the title + prev/next row entirely — used when a caller already
   *  renders its own single month title/nav (the calendar template's month
   *  switcher pill) and only needs the day grid underneath it. */
  hideHeader?: boolean;
}) {
  // Works inside either a RangeCalendar (DateRangePicker) or a plain Calendar
  // (DatePicker) — exactly one of these contexts is non-null depending on
  // which root rendered it, and both expose the same `visibleRange` shape.
  const rangeState = useContext(RangeCalendarStateContext);
  const singleState = useContext(CalendarStateContext);
  const state = rangeState ?? singleState;
  const isRange = rangeState != null;
  const panelDate = state ? state.visibleRange.start.add({ months: offset }) : null;
  const title = panelDate
    ? new Intl.DateTimeFormat(DATE_LOCALE, { month: "long", year: "numeric" }).format(
        panelDate.toDate(getLocalTimeZone()),
      )
    : "";

  return (
    <div className={bare ? "w-[296px] shrink-0" : "w-[326px] shrink-0 rounded-2xl bg-background-primary-default p-[15px] shadow-xs"}>
      <div className="flex flex-col gap-5">
        {!hideHeader && (
          <div className="flex items-center justify-between">
            {showPrev ? (
              <RACButton
                slot="previous"
                className="flex size-4 cursor-pointer items-center justify-center rounded-[3px] text-text-secondary outline-none transition-colors duration-150 ease hover:bg-background-secondary-hover"
              >
                <ChevronLeft16 />
              </RACButton>
            ) : (
              <span className="size-4" aria-hidden />
            )}
            <span className="flex-1 text-center text-body-medium text-text-primary">{title}</span>
            {showNext ? (
              <RACButton
                slot="next"
                className="flex size-4 cursor-pointer items-center justify-center rounded-[3px] text-text-secondary outline-none transition-colors duration-150 ease hover:bg-background-secondary-hover"
              >
                <ChevronRight16 />
              </RACButton>
            ) : (
              <span className="size-4" aria-hidden />
            )}
          </div>
        )}
        <CalendarGrid
          offset={{ months: offset }}
          weekdayStyle="short"
          className="-m-3 self-start border-separate outline-none"
          style={{ borderSpacing: "12px 12px" }}
        >
          <CalendarGridHeader>
            {(day) => (
              <CalendarHeaderCell className="size-6 pb-0 text-center text-body-medium text-text-secondary">
                {day.slice(0, 2)}
              </CalendarHeaderCell>
            )}
          </CalendarGridHeader>
          <CalendarGridBody>
            {(date) => (
              <CalendarCell date={date} className="p-0 outline-none">
                {(cellProps) => <DayCell {...cellProps} isRange={isRange} showToday={showToday} />}
              </CalendarCell>
            )}
          </CalendarGridBody>
        </CalendarGrid>
      </div>
    </div>
  );
}

/** One editable "DD/MM/YYYY" chip. Keeps its own draft text while typing so
 *  the field doesn't reformat on every keystroke; commits on blur/Enter,
 *  reverting to the last valid value if the text doesn't parse. */
export function DateChipInput({
  date,
  label,
  onCommit,
}: {
  date: CalendarDate;
  label: string;
  onCommit: (date: CalendarDate) => void;
}) {
  const formatted = formatChipDate(date);
  const [text, setText] = useState(formatted);
  // 外部日期变了就同步草稿文本。
  //
  // 原来是 `useEffect(() => setText(formatted), [formatted])`，两个毛病：
  // ① 触发 react-hooks/set-state-in-effect（级联渲染）；
  // ② effect 在**提交之后**才跑，等于先渲染一帧旧文本再被纠正。
  //
  // 改成渲染期调整（React 官方「prop 变化时调整 state」模式）：在返回 JSX 前
  // 直接比对并 setState，React 会立刻用新 state 重跑这次渲染，**不提交**中间那帧。
  // `syncedFrom` 是收敛用的哨兵，保证只调整一次，不会死循环。
  const [syncedFrom, setSyncedFrom] = useState(formatted);
  if (formatted !== syncedFrom) {
    setSyncedFrom(formatted);
    setText(formatted);
  }

  const commit = () => {
    const parsed = parseChipDate(text);
    if (parsed) {
      onCommit(parsed);
    } else {
      setText(formatted);
    }
  };

  return (
    <input
      type="text"
      inputMode="numeric"
      value={text}
      onChange={(event) => setText(event.target.value)}
      onBlur={commit}
      onKeyDown={(event) => {
        if (event.key === "Enter") event.currentTarget.blur();
        if (event.key === "Escape") setText(formatted);
      }}
      aria-label={label}
      className="w-[104px] rounded-2lg border border-border-button-default bg-background-primary-default px-2 py-2 text-body-medium text-text-primary shadow-xs outline-none transition-colors duration-100 ease-out focus-visible:border-border-button-active"
    />
  );
}

